pub fn encode(message: Vec<char>) -> Vec<char> {
    // Helper to check if a character is one of the vowels (upper or lower case)
    fn is_vowel(c: char) -> bool {
        matches!(
            c,
            'a' | 'e' | 'i' | 'o' | 'u'
                | 'A' | 'E' | 'I' | 'O' | 'U'
        )
    }

    // Helper to perform the vowel mapping (before case swap)
    fn map_vowel(c: char) -> char {
        match c {
            'a' => 'c',
            'e' => 'g',
            'i' => 'k',
            'o' => 'q',
            'u' => 'w',
            'A' => 'C',
            'E' => 'G',
            'I' => 'K',
            'O' => 'Q',
            'U' => 'W',
            _ => unreachable!("Called map_vowel on non-vowel"),
        }
    }

    let mut result = Vec::with_capacity(message.len());
    for c in message {
        let out = if c == ' ' {
            // Space remains a space
            ' '
        } else if is_vowel(c) {
            // Map the vowel and then swap its case
            let mapped = map_vowel(c);
            if mapped.is_ascii_lowercase() {
                mapped.to_ascii_uppercase()
            } else {
                mapped.to_ascii_lowercase()
            }
        } else {
            // Consonant: just swap case
            if c.is_ascii_lowercase() {
                c.to_ascii_uppercase()
            } else {
                c.to_ascii_lowercase()
            }
        };
        result.push(out);
    }
    result
}

